cards.solution:
function hitungPer<T>(a: T[], kunci: (x: T) => string): Record<string, number> {
  const hasil: Record<string, number> = {};
  for (const x of a) {
    const k = kunci(x);
    hasil[k] = (hasil[k] ?? 0) + 1;
  }
  return hasil;
}
console.log(hitungPer(["kopi", "teh", "kopi", "jus", "kopi"], (x) => x[0]));
